const slugify=value=>value.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const idSuffix=index=>String(index).padStart(12,'0');
const indefiniteArticle=value=>{
  const normalized=String(value).trim();
  if(/^(?:uni(?:on|vers|form)|use|user|euro)/i.test(normalized))return'a';
  return/^[aeiou]/i.test(normalized)?'an':'a';
};
const conversationalFirstName=name=>String(name).replace(/^(?:Dr\.|Commander)\s+/,'').split(/\s+/)[0];
export const characters=characterSeeds.map((item,index)=>{
  const [name,age,gender,pronouns,background,districtSlug,workSlug,secondarySlug,socialSlug,occupation,traits,interests,dialogueTone,quirks,spiceLevel,romanceStyle,storyHook,appearance]=item;
  const slug=slugify(name); const rosterId=index+1;
  return{rosterId,templateId:`24000000-0000-4000-8012-${idSuffix(rosterId)}`,versionId:`25000000-0000-4000-8012-${idSuffix(rosterId)}`,name,slug,age,gender,pronouns,background,classification:'human colonist',districtSlug,workSlug,secondarySlug,socialSlug,occupation,traits,interests,dialogueTone,quirks,spiceLevel,romanceStyle,storyHook,appearance,portraitAssetKey:`eos-meridian-character-${slug}`,
    biography:`${name}, ${age}, is ${indefiniteArticle(occupation)} ${occupation.toLowerCase()} in Eos Meridian. ${traits.join(', ')}. ${storyHook}`,
    relationshipGoal:'either',
    relationshipConfig:{initialStage:'stranger',initialFamiliarity:6,initialTrust:10,initialAttraction:spiceLevel===3?10:7,initialComfort:8,initialChemistry:spiceLevel===3?11:7},
    boundaries:['No coercion','Work authority never implies romantic or sexual consent','Private information is shared according to earned trust','The user may choose pace and direction'],
    communicationStyle:{directness:(traits.includes('direct')||traits.includes('blunt')) ? 0.82 : 0.68,verbosity:'adaptive',questionStyle:'Ask one relevant, character-specific question when curiosity is natural; do not append generic questions to every reply.',dialogueTone},
    voiceProfile:{voiceKey:`eos-${slug}`,delivery:dialogueTone,xaiVoiceId:(gender==='man'?['leo','rex','sal']:['eve','ara','sal'])[rosterId%3]},
    firstMeeting:{locationSlug:workSlug,opener:`You meet ${name} at ${locations.find(location=>location.slug===workSlug)?.name??'their usual place'} during an ordinary part of their routine. ${conversationalFirstName(name)} has a reason to speak with you that comes from the immediate setting rather than instant attraction.`},
    characterBible:{name,age,gender,pronouns,background,occupation,traits,interests,dialogueTone,quirks:quirks.split(';').map(value=>value.trim()),storyHook,romanceStyle,identityFacts:[`I am ${age} years old.`,`I am ${indefiniteArticle(occupation)} ${occupation.toLowerCase()} in Eos Meridian.`,`My home world is Eos Meridian.`,`My usual work location is ${locations.find(location=>location.slug===workSlug)?.name}.`],closedWorldKnowledge:'Knows Eos Meridian, its established residents and Kivelli canon. Does not reference real Earth people, brands, cities, countries, or current events as personal knowledge.',initiativeFoundation:{questionStyle:'Ask about specific details the user introduced, follow unresolved threads, and occasionally volunteer a relevant part of ordinary life.',repairStyle:'If a response misses the user’s intent, acknowledge the mismatch in character and answer the actual point without defensive meta commentary.'}},
  };
});

